import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Estado del combate y preguntas abiertas","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/status-and-open-questions.md","filePath":"es/game-design/combat/status-and-open-questions.md"}'),d={name:"es/game-design/combat/status-and-open-questions.md"};function o(s,a,r,c,l,m){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="combat-status-and-open-questions" tabindex="-1">Estado del combate y preguntas abiertas <a class="header-anchor" href="#combat-status-and-open-questions" aria-label="Enlace permanente a &quot;Estado del combate y preguntas abiertas&quot;">​</a></h1><p><strong>Estado del diseño: mixto, detallado abajo. Revisión: 2026-10-08. Este es un resumen de navegación y reconciliación; las páginas enlazadas definen las reglas.</strong></p><p><a href="/Syrolands-Public/es/guide/combat/overview.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a></p><h2 id="design-implementation-and-evidence" tabindex="-1">Diseño, implementación y evidencia <a class="header-anchor" href="#design-implementation-and-evidence" aria-label="Enlace permanente a &quot;Diseño, implementación y evidencia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mecánica</th><th>Estado del diseño</th><th>Límite de implementación / evidencia</th></tr></thead><tbody><tr><td>Combate automático por defecto y resuelto por el servidor</td><td>Aceptado</td><td>Baseline existente; sin entrada manual nueva en Batch 03</td></tr><tr><td>Siete regiones humanas, umbrales de integridad y ciclo de sesión</td><td>Política con estado Aceptado y Experimental</td><td>Estado local de Stage 2A; las reglas exactas siguen en <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">regiones corporales</a></td></tr><tr><td>Hits globales distintos del trauma local; residual ×2 con condición de ciclo de vida/HP</td><td>Política con estado Aceptado y Experimental</td><td>Integración cuerpo a cuerpo natural de Stage 2A; <a href="/Syrolands-Public/es/game-design/combat/damage.html">daño</a> define la aritmética sin cambios</td></tr><tr><td>Cobertura/contacto y desgaste de armadura compartida</td><td>Adaptador con estado Aceptado y Experimental</td><td>Adaptador heredado; no física ampliada de materiales</td></tr><tr><td>Información cualitativa de Anatomy</td><td>Comportamiento acotado con estado Aceptado</td><td>Stage 2A; los <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">límites de información</a> no cambian</td></tr><tr><td>Región apuntada</td><td>Dirección con estado Aceptado y política de resolución Experimental</td><td>Existe resolución pura; intención del jugador e integración de impacto aplazadas, no apuntado en vivo</td></tr><tr><td>Brazo de apoyo del escudo Disabled</td><td>Consecuencia con estado Aceptado; convención Experimental de Left Arm</td><td>Existen primitivas de transición; guardado del escudo/restricción de equipamiento aplazados</td></tr><tr><td>Otras penalizaciones de incapacitación, sangrado, heridas especializadas y Healing</td><td>Propuesto / Sin resolver</td><td>No se establecen mediante la primitiva de estado local</td></tr><tr><td>Familias de armas, transmisión de materiales, efectos de estado y rasgos</td><td>Propuesto / Sin resolver</td><td>Sin implementación nueva en este batch</td></tr><tr><td>Stamina ampliada, recuperación e influencia acotada de stats</td><td>Propuesto / Sin resolver</td><td>El comportamiento heredado permanece; el rediseño no está implementado</td></tr><tr><td>Entrada de ataque manual</td><td>Propuesto; compatibilidad Sin resolver</td><td><a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html#automatic-baseline-and-manual-input-conflict">Conflicto con entrada obligatoria</a>; sin asignación ni contrato elegidos</td></tr><tr><td>Presión sobre Concentration</td><td>Propuesto / Sin resolver</td><td><a href="/Syrolands-Public/es/game-design/magic.html#concentration-under-pressure">Magia</a> define el diseño</td></tr></tbody></table><p>Se registran comprobaciones automatizadas y una primera observación del cliente, pero aquí no se verifica la disponibilidad actual. La observación inicial no establece equilibrio, ciclo de vida completo, interacciones de armadura ni validación completa de Anatomy. No se ejecutó ninguna sesión de juego nueva para esta documentación.</p><h2 id="unresolved-decisions" tabindex="-1">Decisiones con estado Sin resolver <a class="header-anchor" href="#unresolved-decisions" aria-label="Enlace permanente a &quot;Decisiones con estado Sin resolver&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Preguntas conservadas para diseño y evaluación posteriores</th></tr></thead><tbody><tr><td>Ubicación e intención</td><td>Distribución natural definitiva de extremidades; precisión, coste y factores de apuntado. Los pesos experimentales existentes y la política de apuntado del 50% permanecen intactos, no son equilibrio definitivo.</td></tr><tr><td>Stamina y ritmo</td><td>Costes de ataque, representación de fatiga, regeneración, tiempos de recuperación, intentos fallados/cancelados y presión de acciones repetidas.</td></tr><tr><td>Stats y habilidades marciales</td><td>Contribuciones acotadas de DEX y STR; función de Tactics más allá de escalar daño; evitar un conjunto universal obligatorio de arma/Tactics/Anatomy/Healing.</td></tr><tr><td>Lesiones y medicina</td><td>Umbrales de sangrado, tipos de heridas, Healing/estabilización, recuperación local y persistencia más allá de la configuración de sesión.</td></tr><tr><td>Armadura y equipo</td><td>Penetración/desviación, transmisión contundente, capas, transiciones de estado e interacciones exactas de rasgos especiales con extremidades/armadura.</td></tr><tr><td>Equilibrio de combate</td><td>Objetivos de tiempo para matar en PvP y escalado en PvM; reglas compartidas sin imponer anatomía humana a toda criatura.</td></tr><tr><td>Criaturas y alcance</td><td>Elegibilidad de NPC, perfiles de criaturas grandes, anatomía no humana y disparos dirigidos a distancia.</td></tr><tr><td>Entrada y animación</td><td>Si los ataques manuales son opcionales o reemplazan los automáticos; tiempos de armas, capacidades de animación y límites del cliente.</td></tr><tr><td>Red y acceso</td><td>Red de entrada reactiva, equidad ante latencia, reasignación/accesibilidad, implicaciones antimacro/automatización y comportamiento de clientes no compatibles.</td></tr></tbody></table><h2 id="canonical-ownership-and-reconciliation" tabindex="-1">Responsabilidad canónica y reconciliación <a class="header-anchor" href="#canonical-ownership-and-reconciliation" aria-label="Enlace permanente a &quot;Responsabilidad canónica y reconciliación&quot;">​</a></h2><p>Se preservan el <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">modelo corporal</a>, la <a href="/Syrolands-Public/es/game-design/combat/damage.html">política de trauma</a>, la <a href="/Syrolands-Public/es/game-design/combat/targeting.html">resolución de apuntado</a> y la <a href="/Syrolands-Public/es/game-design/combat/disability.html">regla de escudo</a>. Batch 03 amplía la propuesta a su alrededor; no sustituye silenciosamente experimentos aceptados. <a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Identidad de armas</a>, <a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">interacción de armadura</a> y <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">stamina/entrada</a> centralizan las nuevas direcciones.</p><p><a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Definiciones de calidad</a>, <a href="/Syrolands-Public/es/game-design/characters/stats.html">stats</a>, <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">habilidades y conocimiento</a>, <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">mantenimiento profesional</a>, <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">economía de pérdida</a> y <a href="/Syrolands-Public/es/game-design/magic.html">Magia</a> conservan su propia autoridad. El equipo avanzado con estado Propuesto no puede cambiar implícitamente la fórmula de trauma del prototipo ni la posibilidad aceptada de reemplazo.</p><h2 id="related-design" tabindex="-1">Diseño relacionado <a class="header-anchor" href="#related-design" aria-label="Enlace permanente a &quot;Diseño relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado y decisiones sin resolver</a></p><h2 id="batch-05-normalization-—-proposed" tabindex="-1">Normalización de Batch 05 — Propuesto <a class="header-anchor" href="#batch-05-normalization-—-proposed" aria-label="Enlace permanente a &quot;Normalización de Batch 05 — Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Legacy/Modern</a> aclara la ambigüedad anterior entre opcionalidad y reemplazo: Modern es preferido para experimentos; Legacy se conserva como alternativa compatible. Ningún fundamento automático se reclasifica silenciosamente. Acciones, comportamiento de cola/cancelación, defensa inmediata, Flow, alcance, liberación de disparos y Familiarity compartida siguen con estado Propuesto.</p><p><a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">El registro de 40 conceptos</a> centraliza definiciones, responsables y necesidades de ajuste. Las preguntas abiertas incluyen tiempos de entradas válidas, solapamiento/recuperación de acciones, viabilidad espacial/visual, cambio de modos, latencia/accesibilidad, caducidad de resultados de disparo almacenados, cobro de recursos, mantenimiento por días activos/antimacro, acceso a entrenamiento, cambios de repertorio, ventanas de Flow y compromisos numéricos explícitos. Ningún valor nuevo sustituye políticas experimentales existentes.</p><h2 id="batch-06-—-experimental-numbers-no-gameplay-change" tabindex="-1">Batch 06 — valores con estado Experimental, sin cambio de juego <a class="header-anchor" href="#batch-06-—-experimental-numbers-no-gameplay-change" aria-label="Enlace permanente a &quot;Batch 06 — valores con estado Experimental, sin cambio de juego&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">prototipo numérico</a> y la <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html#batch-06-implementation-triage">clasificación de 40 variables</a> definen una prueba futura acotada. Los valores de fases/recursos/cadencia tienen estado Experimental; Modern sigue Propuesto. Las políticas de salud, trauma y autoridad con estado Aceptado no cambian. Integración del daño, alcance visible, latencia, accesibilidad y controles de abuso del mantenimiento siguen impidiendo afirmar que esté implementado.</p>',18)])])}const b=e(d,[["render",o]]);export{u as __pageData,b as default};
